EXPECTED_PNG_SHA256 = "02a816c66a874c48e0d3ed528f48a0aba900bbfa4b7113e8240e4732b903aaac"
EXPECTED_RGBA_SHA256 = "3d8ec8e3b7255aa2ad656a10b4c274d5ee800c69f2e80f959e3929d8fbf8b0f1"
EXPECTED_RGBA_BYTES = 320 * 240 * 4


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected 1 anchor, found {count}")
    return text.replace(old, new, 1)


def regex_once(text: str, pattern: str, replacement, label: str, flags: int = 0) -> str:
    result, count = re.subn(pattern, replacement, text, count=1, flags=flags)
    if count != 1:
        raise RuntimeError(f"{label}: expected 1 match, found {count}")
    return result


def find_matching_brace(text: str, open_index: int) -> int:
    if open_index < 0 or open_index >= len(text) or text[open_index] != "{":
        raise RuntimeError("invalid opening brace index")

    depth = 0
    i = open_index
    state = "code"

    while i < len(text):
        ch = text[i]
        nxt = text[i + 1] if i + 1 < len(text) else ""

        if state == "code":
            if ch == "/" and nxt == "/":
                state = "line_comment"
                i += 2
                continue
            if ch == "/" and nxt == "*":
                state = "block_comment"
                i += 2
                continue
            if ch == '"':
                state = "string"
                i += 1
                continue
            if ch == "'":
                state = "char"
                i += 1
                continue
            if ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    return i
            i += 1
            continue

        if state == "line_comment":
            if ch == "\n":
                state = "code"
            i += 1
            continue

        if state == "block_comment":
            if ch == "*" and nxt == "/":
                state = "code"
                i += 2
            else:
                i += 1
            continue

        if state in ("string", "char"):
            if ch == "\\":
                i += 2
                continue
            if (state == "string" and ch == '"') or (
                state == "char" and ch == "'"
            ):
                state = "code"
            i += 1
            continue

    raise RuntimeError("matching closing brace not found")


def find_function_definition(text: str, signature: str) -> tuple[int, int, int]:
    pattern = re.compile(
        r"(?m)^" + re.escape(signature) + r"[ \t]*\n?[ \t]*\{"
    )
    match = pattern.search(text)
    if not match:
        raise RuntimeError(f"function definition not found: {signature}")

    open_index = text.find("{", match.start(), match.end())
    close_index = find_matching_brace(text, open_index)
    return match.start(), open_index, close_index


def main() -> int:
    root = Path.cwd().resolve()
    hud_path = root / "src" / "avp" / "hud.c"
    main_path = root / "src" / "main_3ds.c"

    if (
        not hud_path.is_file()
        or not main_path.is_file()
        or not (root / "Makefile.3ds").is_file()
    ):
        print("ERROR: run this from C:/Projects/AvP3DS/Source")
        print("Nothing changed.")
        return 1

    hud_original = hud_path.read_text(encoding="utf-8")
    main_original = main_path.read_text(encoding="utf-8")

    if MARKER in hud_original or MARKER in main_original:
        print("ERROR: PRED-HUD1F is already installed.")
        print("Nothing changed.")
        return 1

    for required in (
        "AVP-HUD1F",
        "AVP-HUD1G1",
        "PRED-HUD1A-SPECIES-ISOLATED",
        "PRED-HUD1B2-SPECIES-ISOLATED",
        "PRED-HUD1C3-NATIVE-BACKDROP",
        "PRED-HUD1D2-BACKDROP-DOWN8",
        "PRED-HUD1E3-SWAP-AND-DEATH-BLACK",
    ):
        if required not in main_original and required not in hud_original:
            print(f"ERROR: required baseline marker missing: {required}")
            print("Nothing changed.")
            return 1

    marine_entries = (
        "{ 84.0f, 36.0f, 144.0f, 88.0f, 1.35f }",
        "{ 10.0f, 124.0f, 86.0f, 78.0f, 1.00f }",
        "{ 208.0f, 124.0f, 112.0f, 78.0f, 0.82f }",
        "{ 40.0f, 0.0f, 240.0f, 32.0f, 0.86f }",
    )

    for entry in marine_entries:
        if main_original.count(entry) != 1:
            print(f"ERROR: sealed Marine layout entry missing or duplicated: {entry}")
            print("Nothing changed.")
            return 1

    if main_original.count("0x000000FF") != 1:
        print("ERROR: universal black lower-screen clear is not in the expected state.")
        print("Nothing changed.")
        return 1

    if "const float topY = 12.0f;" not in main_original:
        print("ERROR: Predator +12 backdrop offset is not in the expected state.")
        print("Nothing changed.")
        return 1

    try:
        png_bytes = zlib.decompress(base64.b64decode(PNG_ZLIB_B64))
        rgba_bytes = zlib.decompress(base64.b64decode(RGBA_ZLIB_B64))
    except Exception as exc:
        print(f"ERROR: embedded asset decode failed: {exc}")
        print("Nothing changed.")
        return 1

    if len(rgba_bytes) != EXPECTED_RGBA_BYTES:
        print(
            f"ERROR: embedded RGBA size is {len(rgba_bytes)}, "
            f"expected {EXPECTED_RGBA_BYTES}"
        )
        print("Nothing changed.")
        return 1

    if sha256(png_bytes) != EXPECTED_PNG_SHA256:
        print("ERROR: embedded PNG hash verification failed.")
        print("Nothing changed.")
        return 1

    if sha256(rgba_bytes) != EXPECTED_RGBA_SHA256:
        print("ERROR: embedded RGBA hash verification failed.")
        print("Nothing changed.")
        return 1

    hud = hud_original
    main_c = main_original

    try:
        # --------------------------------------------------------------
        # hud.c: capture group and prototype.
        # --------------------------------------------------------------
        hud = regex_once(
            hud,
            r"(?m)^(?P<i>[ \t]*)#define[ \t]+"
            r"AVP3DS_HUD_GROUP_PRED_MESSAGES[ \t]+6[ \t]*$",
            lambda m: (
                f"{m.group('i')}#define AVP3DS_HUD_GROUP_PRED_MESSAGES 6\n"
                f"{m.group('i')}#define AVP3DS_HUD_GROUP_PRED_AMMO     7"
            ),
            "hud.c Predator ammo group define",
        )

        hud = replace_once(
            hud,
            "void DisplayPredatorHealthAndEnergy(void);\n",
            "void DisplayPredatorHealthAndEnergy(void);\n"
            "static void DisplayPredatorSpearAmmo(void);\n",
            "Predator spear ammo prototype",
        )

        # --------------------------------------------------------------
        # Split spear ammo out of DisplayPredatorHealthAndEnergy().
        # --------------------------------------------------------------
        function_start, function_open, function_close = find_function_definition(
            hud,
            "void DisplayPredatorHealthAndEnergy(void)",
        )

        function_text = hud[function_start:function_close + 1]

        function_text, declaration_count = re.subn(
            r"(?m)^[ \t]*PLAYER_WEAPON_DATA[ \t]*\*weaponPtr[ \t]*="
            r"[^\n]*;\n",
            "",
            function_text,
            count=1,
        )
        if declaration_count != 1:
            raise RuntimeError(
                "weaponPtr declaration removal: "
                f"expected 1, found {declaration_count}"
            )

        ammo_if = function_text.find(
            "if (weaponPtr->WeaponIDNumber == WEAPON_PRED_RIFLE)"
        )
        if ammo_if < 0:
            raise RuntimeError("spear ammo block start not found")

        ammo_open = function_text.find("{", ammo_if)
        ammo_close = find_matching_brace(function_text, ammo_open)
        ammo_block = function_text[ammo_if:ammo_close + 1]

        function_text = (
            function_text[:ammo_if].rstrip()
            + "\n\n"
            + function_text[ammo_close + 1:].lstrip()
        )

        # The extracted block keeps the game's original ammo digits and color.
        spear_function = f"""

/*
 * {MARKER}: spear-gun ammo is captured independently so it cannot
 * change the health/field-charge bounds or move those rails.
 */
static void DisplayPredatorSpearAmmo(void)
{{
    PLAYER_WEAPON_DATA *weaponPtr =
        &(PlayerStatusPtr->WeaponSlot[
            PlayerStatusPtr->SelectedWeaponSlot]);

    int value;
    int i;
    int scale = DIV_FIXED(ScreenDescriptorBlock.SDB_Width,640);
    int size = MUL_FIXED(51,scale);

    {ammo_block}
}}
"""

        hud = (
            hud[:function_start]
            + function_text
            + spear_function
            + hud[function_close + 1:]
        )

        # --------------------------------------------------------------
        # Capture the new function immediately after Predator status capture.
        # --------------------------------------------------------------
        caller_anchor = """                                    DisplayPredatorHealthAndEnergy();

                                    #ifdef __3DS__
                                    AvP3DS_EndHUDCapture();
                                    #endif
"""

        caller_replacement = caller_anchor + f"""
                                    /* {MARKER}: spear-gun ammo only. */
                                    #ifdef __3DS__
                                    AvP3DS_BeginHUDCapture(
                                        AVP3DS_HUD_GROUP_PRED_AMMO);
                                    #endif

                                    DisplayPredatorSpearAmmo();

                                    #ifdef __3DS__
                                    AvP3DS_EndHUDCapture();
                                    #endif
"""

        hud = replace_once(
            hud,
            caller_anchor,
            caller_replacement,
            "Predator ammo caller capture",
        )

        # --------------------------------------------------------------
        # main_3ds.c: group 7, count 8, and center ammo layout.
        # --------------------------------------------------------------
        main_c = regex_once(
            main_c,
            r"(?m)^#define[ \t]+AVP3DS_HUD_GROUP_PRED_MESSAGES[ \t]+6[ \t]*\n"
            r"#define[ \t]+AVP3DS_HUD_GROUP_COUNT[ \t]+7[ \t]*$",
            (
                "#define AVP3DS_HUD_GROUP_PRED_MESSAGES 6\n"
                "#define AVP3DS_HUD_GROUP_PRED_AMMO     7\n"
                "#define AVP3DS_HUD_GROUP_COUNT         8"
            ),
            "main_3ds.c group 7/count 8",
        )

        main_c = regex_once(
            main_c,
            r"(?ms)"
            r"(?P<comment>[ \t]*/\* PRED-HUD1B2: Predator ticker in "
            r"second checker row\. \*/[ \t]*\n)"
            r"(?P<entry>[ \t]*\{[ \t]*40\.0f,[ \t]*16\.0f,[ \t]*240\.0f,"
            r"[ \t]*32\.0f,[ \t]*0\.86f[ \t]*\})"
            r"(?P<close>[ \t]*\n\};)",
            lambda m: (
                f"{m.group('comment')}"
                f"{m.group('entry')},\n\n"
                "    /* PRED-HUD1F: spear-gun ammo in center red box. */\n"
                "    { 116.0f, 72.0f, 88.0f, 32.0f, 1.25f }"
                f"{m.group('close')}"
            ),
            "Predator ammo layout box",
        )

        # Predator-frame detection also recognizes the new ammo group.
        main_c = replace_once(
            main_c,
            "            capturedGroup == AVP3DS_HUD_GROUP_PRED_MESSAGES)\n",
            "            capturedGroup == AVP3DS_HUD_GROUP_PRED_MESSAGES ||\n"
            "            capturedGroup == AVP3DS_HUD_GROUP_PRED_AMMO)\n",
            "Predator detector ammo extension",
        )

        # --------------------------------------------------------------
        # Lock status transform and pin message top-left.
        # --------------------------------------------------------------
        static_anchor = (
            "static bool avp3ds_tracker_transform_locked = false;\n"
            "static AvP3DS_HUDGroupTransform avp3ds_tracker_locked_transform;\n"
        )
        static_replacement = static_anchor + f"""
/* {MARKER}: stable Predator rails independent of selected weapon. */
static bool avp3ds_predator_status_transform_locked = false;
static AvP3DS_HUDGroupTransform
    avp3ds_predator_status_locked_transform;
"""
        main_c = replace_once(
            main_c,
            static_anchor,
            static_replacement,
            "Predator status transform lock state",
        )

        tracker_if = main_c.find(
            "        if (group == AVP3DS_HUD_GROUP_TRACKER)\n"
        )
        if tracker_if < 0:
            raise RuntimeError("tracker transform lock branch not found")

        tracker_open = main_c.find("{", tracker_if)
        tracker_close = find_matching_brace(main_c, tracker_open)

        pinning_code = f"""
        else if (group == AVP3DS_HUD_GROUP_PRED_STATUS)
        {{
            /*
             * {MARKER}: after spear ammo is separated, the first status
             * capture contains only the two rails. Keep that transform.
             */
            if (!avp3ds_predator_status_transform_locked)
            {{
                avp3ds_predator_status_locked_transform =
                    transforms[group];

                avp3ds_predator_status_transform_locked = true;
            }}
            else
            {{
                transforms[group] =
                    avp3ds_predator_status_locked_transform;
            }}
        }}
        else if (group == AVP3DS_HUD_GROUP_PRED_MESSAGES)
        {{
            /*
             * Keep the message strip's top-left anchor fixed while allowing
             * its live content width and scale to remain adaptive.
             */
            transforms[group].offsetX = box->x;
            transforms[group].offsetY = box->y;
        }}
"""

        main_c = (
            main_c[:tracker_close + 1]
            + pinning_code
            + main_c[tracker_close + 1:]
        )

        # --------------------------------------------------------------
        # Final safety checks before any file write.
        # --------------------------------------------------------------
        for entry in marine_entries:
            if main_c.count(entry) != 1:
                raise RuntimeError(f"Marine layout changed: {entry}")

        for required in (
            "AVP-HUD1G1 tracker transform lock",
            "PRED-HUD1E3-SWAP-AND-DEATH-BLACK",
        ):
            if required not in main_c and required not in hud:
                raise RuntimeError(f"required milestone behavior lost: {required}")

        if main_c.count("0x000000FF") != 1:
            raise RuntimeError("death-black clear changed")

        if "const float topY = 12.0f;" not in main_c:
            raise RuntimeError("Predator +12 backdrop offset changed")

        if main_c.count("romfs:/Marine_WY_HUD.rgba") != 1:
            raise RuntimeError("Marine texture path changed")

        if main_c.count("romfs:/Predator_HUD_Backdrop_320x240.rgba") != 1:
            raise RuntimeError("Predator texture path changed")

        if "AVP3DS_HUD_GROUP_COUNT         8" not in main_c:
            raise RuntimeError("HUD group count 8 verification failed")

        if hud.count("DisplayPredatorSpearAmmo();") != 1:
            raise RuntimeError("spear ammo caller verification failed")

        if hud.count("static void DisplayPredatorSpearAmmo(void)") != 2:
            raise RuntimeError(
                "spear ammo prototype/definition verification failed"
            )

        if hud.count(
            "if (weaponPtr->WeaponIDNumber == WEAPON_PRED_RIFLE)"
        ) != 1:
            raise RuntimeError(
                "spear weapon test was not isolated to one function"
            )

        if main_c.count(MARKER) < 2 or hud.count(MARKER) < 2:
            raise RuntimeError("PRED-HUD1F marker verification failed")

    except Exception as exc:
        print(f"ERROR: {exc}")
        print("Nothing changed.")
        return 1

    romfs_dir = root / "romfs"
    assets_dir = root / "assets"
    raw_out = romfs_dir / "Predator_HUD_Backdrop_320x240.rgba"
    png_out = assets_dir / "Predator_HUD_Backdrop_320x240.png"

    main_backup = main_path.with_name("main_3ds.c.pre-PRED-HUD1F.bak")
    hud_backup = hud_path.with_name("hud.c.pre-PRED-HUD1F.bak")
    raw_backup = raw_out.with_name(
        "Predator_HUD_Backdrop_320x240.pre-PRED-HUD1F.rgba.bak"
    )
    png_backup = png_out.with_name(
        "Predator_HUD_Backdrop_320x240.pre-PRED-HUD1F.png.bak"
    )

    for path in (main_backup, hud_backup, raw_backup, png_backup):
        if path.exists():
            print(f"ERROR: backup already exists: {path}")
            print("Nothing changed.")
            return 1

    if not raw_out.is_file() or not png_out.is_file():
        print("ERROR: current Predator backdrop assets are missing.")
        print(f"Expected: {raw_out}")
        print(f"Expected: {png_out}")
        print("Nothing changed.")
        return 1

    shutil.copy2(main_path, main_backup)
    shutil.copy2(hud_path, hud_backup)
    shutil.copy2(raw_out, raw_backup)
    shutil.copy2(png_out, png_backup)

    wrote_main = wrote_hud = wrote_raw = wrote_png = False

    try:
        main_path.write_text(main_c, encoding="utf-8")
        wrote_main = True

        hud_path.write_text(hud, encoding="utf-8")
        wrote_hud = True

        raw_out.write_bytes(rgba_bytes)
        wrote_raw = True

        png_out.write_bytes(png_bytes)
        wrote_png = True

    except Exception as exc:
        if wrote_main:
            shutil.copy2(main_backup, main_path)
        if wrote_hud:
            shutil.copy2(hud_backup, hud_path)
        if wrote_raw:
            shutil.copy2(raw_backup, raw_out)
        if wrote_png:
            shutil.copy2(png_backup, png_out)

        print(f"ERROR while writing: {exc}")
        print("All modified files were restored.")
        return 1

    print("PRED-HUD1F installed successfully.")
    print(f"Backup: {main_backup}")
    print(f"Backup: {hud_backup}")
    print(f"Backup: {raw_backup}")
    print(f"Backup: {png_backup}")
    print()
    print("Predator result:")
    print("  - health/field-charge rails use a stable locked transform")
    print("  - messages retain a fixed top-left anchor")
    print("  - spear-gun ammo uses dedicated group 7")
    print("  - spear ammo target: x=116, y=72, w=88, h=32")
    print("  - new approved backdrop installed")
    print()
    print("Preserved:")
    print("  - Predator backdrop +12 px offset")
    print("  - universal death-black lower screen")
    print("  - complete Marine HUD milestone")
    print(f"RGBA SHA-256: {sha256(rgba_bytes)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
